/*
  B3 Weekly Quiz — "Send to Nigri" (built into the Results tab)
  -------------------------------------------------------------
  Put this file in the same weekly-quiz folder as teacher.html.
  teacher.html loads it (plus jsPDF) right before </body>.

  Same behavior as B3SchoolMarksBridge.html, but it runs inside the teacher
  page: no second password, and it uses the launches / responses /
  completions the teacher page already has loaded live.

  Only shown for B3's own East / West Track (not for ?class=<id> class spaces).
*/
(function () {
  'use strict';
  if (typeof CLASS_SPACE !== 'undefined' && CLASS_SPACE) return;
  if (typeof db === 'undefined' || typeof allLaunches === 'undefined') return;

  // ---------- Settings (same as the bridge) ----------
  const SYNC_URL = 'https://nigrisync.onrender.com/sync-marks';
  const SYNC_KEY = '1qaz2wsx';
  const NIGRI_TYPE_MAP = { 'Quiz': 'quiz', 'Test/Project': 'test', 'Classwork': 'classwork', 'Homework': 'homework' };
  const NIGRI_TOPICS = ['Shoroshim', 'Chumash Comprehension', 'Chumash Translation', 'Chumash Havana', 'Chumash',
    'Chumash-Rashi', 'Chumash-HW', 'Halacha-Yahadus', 'Parsha'];
  const NIGRI_ROSTERS = {
    et: ['chaim_chaikin', 'yossi_gourarie', 'sholom_huebner', 'moshe_lapine', 'kehos_notik', 'yisroel_oirechman', 'moshe_raichman', 'avrohom_rosenfeld', 'levi_rozmarin', 'arik_traxler'],
    wt: ['ari_greenberg', 'zev_rosenfeld', 'levi_schtroks', 'yisroel_aryeh_simmonds', 'leibel_vogel', 'leib_wolf']
  };
  const NIGRI_NAMES = {
    chaim_chaikin: 'Chaikin Mayer Chaim', yossi_gourarie: 'Gourarie Yossi', sholom_huebner: 'Huebner Sholom DovBer',
    moshe_lapine: 'Lapine Moshe', kehos_notik: 'Notik Kehos', yisroel_oirechman: 'Oirechman Yisroel',
    moshe_raichman: 'Raichman Moshe Tuvia', avrohom_rosenfeld: 'Rosenfeld Avrohom', levi_rozmarin: 'Rozmarin Levi',
    arik_traxler: 'Traxler Arik', ari_greenberg: 'Greenberg Ari', zev_rosenfeld: 'Rosenfeld Zev',
    levi_schtroks: 'Schtroks Levi', yisroel_aryeh_simmonds: 'Simmonds Yisroel Aryeh', leibel_vogel: 'Vogel Leibel',
    leib_wolf: 'Wolf Yisroel Arye Leib'
  };

  // Quiz type -> Nigri topic (quiz types are named after the Nigri topics).
  function skillTopic(s) {
    if (s === 'shorashim') return 'Shoroshim';
    if (s === 'translation') return 'Chumash Translation';
    if (s === 'mixed' || s === 'integrated') return 'Chumash';
    return 'Chumash Comprehension';
  }

  // ---------- Small helpers ----------
  const $ = (id) => document.getElementById(id);
  const h = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const arr = (v) => (typeof asArray === 'function' ? asArray(v) : (Array.isArray(v) ? v : []));
  const gradeLabel = (c) => (c === 'wt' ? 'B3 WT' : 'B3 ET');
  function isoDate(ts) { const d = ts ? new Date(Number(ts)) : new Date(); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); }
  function displayName(id) { return (roster[id] && roster[id].name) || id.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()); }
  function questionsOf(l) { return arr(l && l.quizSnapshot && l.quizSnapshot.questions); }
  function quizLinkFor(launchId) {
    if (typeof getLaunchLink === 'function') return getLaunchLink(launchId);
    return 'https://simchacohen1.github.io/B3-games/weekly-quiz/?launch=' + encodeURIComponent(launchId);
  }

  // ---------- Final mark logic (copied from the bridge) ----------
  function rootLaunchId(id) {
    let cur = id, guard = 0;
    while (guard++ < 10) {
      const l = allLaunches[cur] || {}, parent = l.retakeOf || l.makeupOf;
      if (!parent || !allLaunches[parent]) break;
      cur = parent;
    }
    return cur;
  }
  function rawScore(lid, sid) {
    const l = allLaunches[lid]; if (!l) return null;
    const qs = questionsOf(l), sr = (allResponses[lid] || {})[sid] || {};
    let correct = 0, answered = 0;
    qs.forEach((q, i) => { const r = sr[i] || sr[String(i)]; if (r) { answered++; if (r.correct) correct++; } });
    const done = !!(completions[lid] && completions[lid][sid]) || (qs.length > 0 && answered === qs.length);
    return { correct, answered, total: qs.length, pct: qs.length ? Math.round(correct / qs.length * 100) : null, done };
  }
  function relatedToBase(lid, baseId) {
    if (lid === baseId) return true;
    let cur = lid, guard = 0;
    while (guard++ < 10) {
      const l = allLaunches[cur] || {}, parent = l.retakeOf || l.makeupOf;
      if (!parent) return false;
      if (parent === baseId) return true;
      cur = parent;
    }
    const l = allLaunches[lid] || {}, base = allLaunches[baseId] || {};
    return !!((l.attemptGroupId || '') && (l.attemptGroupId === (base.attemptGroupId || baseId)));
  }
  function attemptTag(l) {
    const tags = [];
    if (l.makeupOf) tags.push('Make-Up');
    if (l.retakeOf) tags.push('Retake ' + (l.attemptNumber || 2));
    if (!tags.length) tags.push('Original');
    return tags.join(' ');
  }
  function finalForStudent(baseId, sid) {
    const candidates = [];
    Object.keys(allLaunches).forEach((lid) => {
      if (!relatedToBase(lid, baseId)) return;
      const l = allLaunches[lid] || {}, targets = l.targetStudents ? Object.keys(l.targetStudents).filter((k) => l.targetStudents[k]) : [];
      if (targets.length && !targets.includes(sid)) return;
      if (!targets.length && !((NIGRI_ROSTERS[l.classId] || []).includes(sid))) return;
      const sc = rawScore(lid, sid); if (sc && sc.answered) candidates.push({ lid, l, sc });
    });
    if (!candidates.length) return { mark: null, done: false, source: 'No completed attempt', lid: null };
    const finished = candidates.filter((x) => x.sc.done);
    const pool = finished.length ? finished : candidates;
    pool.sort((a, b) => {
      const an = Number(a.l.attemptNumber) || 1, bn = Number(b.l.attemptNumber) || 1;
      if (an !== bn) return bn - an;
      return (Number(b.l.createdAt) || 0) - (Number(a.l.createdAt) || 0);
    });
    const x = pool[0];
    return { mark: x.sc.done ? x.sc.pct : null, done: x.sc.done, source: attemptTag(x.l), lid: x.lid };
  }

  // ---------- PDF report per student (copied from the bridge) ----------
  const HEBREW_FONT_BASE64 = '';
  const REPORT_FONT = 'NotoSansHebrew';
  function isPureHebrew(s) { const str = String(s || ''); return /[֐-׿]/.test(str) && !/[A-Za-z]/.test(str); }
  function choiceLabel(choices, i) {
    if (i === null || i === undefined || i < 0 || !choices || !choices[i]) return '— no answer —';
    return '(' + String.fromCharCode(65 + i) + ') ' + choices[i];
  }
  function newReportDoc() {
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'pt', format: 'letter' });
    doc.addFileToVFS('NotoSansHebrew.ttf', HEBREW_FONT_BASE64);
    doc.addFont('NotoSansHebrew.ttf', REPORT_FONT, 'normal');
    doc.setFont(REPORT_FONT);
    return doc;
  }
  function drawCell(doc, text, x, width, y, fontSize) {
    doc.setFontSize(fontSize);
    const lines = doc.splitTextToSize(String(text || ''), width), lh = fontSize * 1.3;
    lines.forEach((line, i) => {
      if (isPureHebrew(line)) doc.text(line, x + width, y + i * lh, { align: 'right', R2L: true });
      else doc.text(line, x, y + i * lh, { align: 'left' });
    });
    return Math.max(lines.length, 1) * lh;
  }
  function buildStudentReportPDF(meta, questions, studentResponses) {
    const doc = newReportDoc();
    const pageW = doc.internal.pageSize.getWidth(), pageH = doc.internal.pageSize.getHeight();
    const margin = 40, colNum = 24, gap = 10, colQ = 220, colAns = (pageW - margin * 2 - colNum - gap * 2 - colQ) / 2;
    const xNum = margin, xQ = margin + colNum + gap, xAns1 = xQ + colQ + gap, xAns2 = xAns1 + colAns + gap;
    let y = margin;
    function drawPageHeader() {
      doc.setFillColor(45, 110, 163); doc.rect(0, 0, pageW, 66, 'F');
      doc.setTextColor(255, 255, 255); doc.setFontSize(16);
      doc.text(meta.quizTitle || 'Quiz Report', margin, 28, { align: 'left' });
      doc.setFontSize(10);
      doc.text(meta.className + '  •  ' + meta.dateStr + '  •  ' + meta.attemptTag, margin, 46, { align: 'left' });
      doc.setTextColor(24, 50, 74); y = 90;
      doc.setFontSize(14); doc.text(meta.studentName, margin, y, { align: 'left' });
      doc.setFontSize(12); doc.text(meta.scoreText, pageW - margin, y, { align: 'right' });
      y += 18;
      doc.setFillColor(237, 245, 250); doc.rect(margin, y, pageW - margin * 2, 20, 'F');
      doc.setFontSize(9); doc.setTextColor(24, 50, 74);
      doc.text('#', xNum + 2, y + 14); doc.text('Question', xQ + 2, y + 14);
      doc.text("Student's Answer", xAns1 + 2, y + 14); doc.text('Correct Answer', xAns2 + 2, y + 14);
      y += 26;
    }
    function drawFooters() {
      const n = doc.internal.getNumberOfPages();
      for (let p = 1; p <= n; p++) {
        doc.setPage(p); doc.setFontSize(8); doc.setTextColor(130, 130, 130);
        doc.text('Generated by B3 Weekly Quiz', margin, pageH - 20, { align: 'left' });
        doc.text('Page ' + p + ' of ' + n, pageW - margin, pageH - 20, { align: 'right' });
      }
    }
    drawPageHeader();
    (questions || []).forEach((q, i) => {
      const resp = studentResponses[i] || studentResponses[String(i)] || null;
      const chosenText = resp ? choiceLabel(arr(q.choices), Number(resp.choiceIndex)) : '— no answer —';
      const correctText = choiceLabel(arr(q.choices), Number(q.correctIndex));
      const isCorrect = !!(resp && resp.correct);
      doc.setFontSize(9);
      const qLines = doc.splitTextToSize(String(q.q || ''), colQ - 4).length;
      const aLines = doc.splitTextToSize(chosenText, colAns - 4).length;
      const cLines = doc.splitTextToSize(correctText, colAns - 4).length;
      const rowH = Math.max(qLines, aLines, cLines, 1) * 9 * 1.3 + 10;
      if (y + rowH > pageH - 46) { doc.addPage(); drawPageHeader(); }
      if (i % 2 === 1) { doc.setFillColor(247, 251, 254); doc.rect(margin, y - 4, pageW - margin * 2, rowH, 'F'); }
      doc.setTextColor(24, 50, 74); doc.text(String(i + 1), xNum + 2, y + 8);
      drawCell(doc, q.q || '', xQ + 2, colQ - 4, y + 8, 9);
      if (isCorrect) doc.setTextColor(46, 139, 87); else doc.setTextColor(180, 62, 69);
      drawCell(doc, chosenText, xAns1 + 2, colAns - 4, y + 8, 9);
      doc.setTextColor(24, 50, 74);
      drawCell(doc, correctText, xAns2 + 2, colAns - 4, y + 8, 9);
      y += rowH;
    });
    drawFooters();
    return doc.output('datauristring').split(',')[1];
  }

  // ---------- UI: button in Results + popup panel ----------
  const style = document.createElement('style');
  style.textContent =
    '#nigriModal .modal-box{width:min(860px,96vw);max-height:92vh;overflow:auto}' +
    '#nigriModal .ng-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin:12px 0}' +
    '#nigriModal label{display:flex;flex-direction:column;gap:4px;font-weight:700;font-size:14px}' +
    '#nigriModal table{width:100%;border-collapse:collapse;margin-top:10px}' +
    '#nigriModal th,#nigriModal td{border-bottom:1px solid var(--line);padding:7px 8px;text-align:left;font-size:14px}' +
    '#nigriModal th{background:var(--light)}' +
    '#nigriModal .ng-ok{color:var(--good);font-weight:800}#nigriModal .ng-missing{color:var(--bad);font-weight:800}' +
    '#nigriModal .ng-note{background:#fff8e6;border:1px solid #f0d9a0;border-radius:9px;padding:9px 11px;font-size:13px;margin-top:8px}' +
    '#nigriStatus.ok{color:var(--good);font-weight:800}#nigriStatus.err{color:var(--bad);font-weight:800}';
  document.head.appendChild(style);

  const modal = document.createElement('div');
  modal.id = 'nigriModal';
  modal.className = 'modal-overlay hidden';
  modal.innerHTML =
    '<div class="modal-box">' +
      '<div class="topline"><h2 style="margin:0">Send to Nigri</h2><button type="button" class="secondary" id="nigriClose">Close</button></div>' +
      '<div class="small" id="nigriBaseNote" style="margin-top:4px"></div>' +
      '<div class="ng-grid">' +
        '<label>Nigri Section<input id="nigriSection" type="text" value="Shluchim OS"></label>' +
        '<label>Grade<input id="nigriGrade" type="text"></label>' +
        '<label>Nigri Topic<select id="nigriTopic">' + NIGRI_TOPICS.map((t) => '<option>' + h(t) + '</option>').join('') + '</select></label>' +
        '<label>Nigri Type<select id="nigriType"><option>Quiz</option><option>Test/Project</option><option>Classwork</option><option>Homework</option></select></label>' +
        '<label>Date<input id="nigriDate" type="date"></label>' +
        '<label>Name<input id="nigriName" type="text"></label>' +
      '</div>' +
      '<label>Description<textarea id="nigriDescription" rows="2"></textarea></label>' +
      '<label style="margin-top:8px">Comment on each child (optional)<input id="nigriComment" type="text" placeholder="Leave blank for no comment"></label>' +
      '<div class="ng-note">A boy with a completed quiz defaults to <b>Present</b>. A boy with no completed attempt syncs as <b>0%</b>, and his Nigri comment gets a direct link to take the quiz; his attendance stays <b>Review / leave unchanged</b> unless you pick one.</div>' +
      '<div style="overflow:auto"><table><thead><tr><th>Student</th><th>Final mark</th><th>Used attempt</th><th>Nigri attendance</th></tr></thead><tbody id="nigriStudents"></tbody></table></div>' +
      '<div class="modal-actions" style="justify-content:flex-start"><button type="button" class="good" id="nigriSyncBtn" style="font-size:17px;padding:12px 20px">Save to Nigri</button></div>' +
      '<div id="nigriStatus" class="small" style="margin-top:8px"></div>' +
      '<div class="small" style="margin-top:8px">This creates a new mark on Nigri, fills in every student\'s score, attendance and PDF report, sets "Marking done", and saves. It usually takes 20–40 seconds. Once it says <b>Saved</b>, the marks are on the real Nigri gradebook.</div>' +
    '</div>';
  document.body.appendChild(modal);

  let nigriBaseId = '';

  function openNigri() {
    if (!resultsLaunchId || !allLaunches[resultsLaunchId]) { alert('Choose a test from Quiz History first.'); return; }
    nigriBaseId = rootLaunchId(resultsLaunchId);
    const l = allLaunches[nigriBaseId] || {}, snap = l.quizSnapshot || {}, skill = snap.skillType || 'comprehension';
    if (!NIGRI_ROSTERS[l.classId]) { alert('Nigri sync is only set up for East Track and West Track.'); return; }
    $('nigriBaseNote').textContent = (snap.title || 'Quiz') + ' • ' + gradeLabel(l.classId) +
      (nigriBaseId !== resultsLaunchId ? ' • Using the original test; each boy\'s latest retake / make-up is counted automatically.' : ' • Each boy\'s latest retake / make-up is counted automatically.');
    $('nigriGrade').value = gradeLabel(l.classId);
    $('nigriTopic').value = skillTopic(skill);
    $('nigriType').value = 'Quiz';
    $('nigriDate').value = isoDate(l.createdAt);
    $('nigriName').value = snap.title || 'Weekly Quiz';
    $('nigriDescription').value = '';
    $('nigriComment').value = '';
    $('nigriStatus').textContent = ''; $('nigriStatus').className = 'small';
    const body = $('nigriStudents'); body.innerHTML = '';
    (NIGRI_ROSTERS[l.classId] || []).forEach((sid) => {
      const f = finalForStudent(nigriBaseId, sid), missing = f.mark === null, tr = document.createElement('tr');
      tr.dataset.sid = sid; tr.dataset.mark = missing ? '0' : String(f.mark); tr.dataset.missing = missing ? '1' : '';
      tr.dataset.lid = f.lid || ''; tr.dataset.attempt = f.source || '';
      tr.innerHTML =
        '<td><b>' + h(NIGRI_NAMES[sid] || displayName(sid)) + '</b><div class="small">' + h(displayName(sid)) + '</div></td>' +
        '<td class="' + (missing ? 'ng-missing' : 'ng-ok') + '">' + (missing ? '0% — missing' : f.mark + '%') + '</td>' +
        '<td>' + h(f.source) + '</td>' +
        '<td><select>' + (f.done
          ? '<option value="present" selected>Present</option><option value="absent">Absent</option><option value="review">Leave unchanged</option>'
          : '<option value="review" selected>Review / leave unchanged</option><option value="absent">Absent</option><option value="present">Present</option>') +
        '</select></td>';
      body.appendChild(tr);
    });
    modal.classList.remove('hidden');
  }

  async function syncNigri() {
    const students = [...document.querySelectorAll('#nigriStudents tr')].map((tr) => {
      const sid = tr.dataset.sid, missing = tr.dataset.missing === '1';
      return { id: sid, nigriName: NIGRI_NAMES[sid] || displayName(sid), mark: missing ? 0 : Number(tr.dataset.mark), missing,
        attendance: tr.querySelector('select').value, lid: tr.dataset.lid || null, attempt: tr.dataset.attempt || '' };
    });
    const packet = {
      grade: $('nigriGrade').value.trim(), topic: $('nigriTopic').value, type: $('nigriType').value,
      date: $('nigriDate').value, name: $('nigriName').value.trim(),
      description: $('nigriDescription').value.trim(), comment: $('nigriComment').value.trim()
    };
    if (!packet.name) { alert('Give this mark a Name before saving.'); return; }
    if (!packet.date) { alert('Choose a date before saving.'); return; }
    const unresolved = students.filter((s) => s.attendance === 'review' && s.missing);
    if (unresolved.length && !confirm('These students still say Review / leave unchanged: ' + unresolved.map((s) => s.nigriName).join(', ') + '. Continue without guessing their attendance?')) return;
    if (!confirm('Save "' + packet.name + '" to Nigri as ' + packet.topic + ' (' + packet.grade + ', ' + packet.date + ')?')) return;

    const btn = $('nigriSyncBtn'), status = $('nigriStatus');
    btn.disabled = true; status.className = 'small'; status.textContent = 'Building each student\'s report…';

    const withReports = students.map((s) => {
      if (s.missing || !s.lid || !allLaunches[s.lid] || !window.jspdf) return s;
      try {
        const l = allLaunches[s.lid], sr = (allResponses[s.lid] || {})[s.id] || {};
        const pdf = buildStudentReportPDF({ quizTitle: packet.name, className: packet.grade, dateStr: packet.date,
          attemptTag: s.attempt || attemptTag(l), studentName: s.nigriName, scoreText: 'Score: ' + s.mark + '%' }, questionsOf(l), sr);
        const safeName = (s.nigriName || 'student').replace(/[^A-Za-z0-9 _-]/g, ''), safeQuiz = (packet.name || 'Report').replace(/[^A-Za-z0-9 _-]/g, '');
        return Object.assign({}, s, { report_base64: pdf, report_filename: safeName + ' - ' + safeQuiz + '.pdf' });
      } catch (e) { console.error('Report build failed for', s.nigriName, e); return s; }
    });

    const body = {
      class_section: packet.grade, topic: packet.topic, test_name: packet.name,
      type: NIGRI_TYPE_MAP[packet.type] || 'quiz', date: packet.date, description: packet.description,
      students: withReports.map((s) => {
        let comment = packet.comment || undefined;
        if (s.missing) comment = 'Did not take this quiz yet. Take it here: ' + quizLinkFor(nigriBaseId) + (packet.comment ? ' — ' + packet.comment : '');
        return { name: s.nigriName, mark: s.mark, attendance: s.attendance, comment, report_base64: s.report_base64, report_filename: s.report_filename };
      })
    };

    status.textContent = 'Saving to Nigri… this can take under a minute, please wait.';
    try {
      const res = await fetch(SYNC_URL, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Sync-Key': SYNC_KEY }, body: JSON.stringify(body) });
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.status === 'success') {
        const failed = (data.results || []).filter((r) => String(r).includes('FAILED'));
        status.className = 'ok';
        status.textContent = 'Saved to Nigri! (mark #' + data.test_id + ')' + (failed.length ? ' — but check these: ' + failed.join('; ') : '');
        try {
          await db.ref(QROOT + '/launches/' + nigriBaseId + '/nigriSync').set({
            at: firebase.database.ServerValue.TIMESTAMP, testId: data.test_id || '', topic: packet.topic, name: packet.name, date: packet.date
          });
        } catch (e) { console.warn('Could not record Nigri sync on the launch:', e); }
      } else {
        status.className = 'err';
        status.textContent = 'Nigri did not save this: ' + (data.detail || 'Unknown error (' + res.status + ').');
      }
    } catch (e) {
      status.className = 'err';
      status.textContent = 'Could not reach the sync service: ' + e.message;
    } finally { btn.disabled = false; }
  }

  $('nigriClose').addEventListener('click', () => modal.classList.add('hidden'));
  $('nigriSyncBtn').addEventListener('click', syncNigri);

  // Button next to Download CSV in the Results tab.
  const controls = document.querySelector('#panelResults .controls');
  if (controls && !$('nigriOpenBtn')) {
    const btn = document.createElement('button');
    btn.id = 'nigriOpenBtn'; btn.type = 'button'; btn.className = 'good'; btn.textContent = 'Send to Nigri';
    btn.addEventListener('click', openNigri);
    controls.insertBefore(btn, controls.firstChild);
  }

  // Show "Already sent to Nigri" on the button when this test was synced before.
  function refreshNigriButton() {
    const btn = $('nigriOpenBtn'); if (!btn) return;
    const base = resultsLaunchId ? allLaunches[rootLaunchId(resultsLaunchId)] : null, s = base && base.nigriSync;
    btn.textContent = s ? 'Send to Nigri again' : 'Send to Nigri';
    btn.title = s ? 'Already saved to Nigri on ' + new Date(Number(s.at)).toLocaleDateString() + ' as ' + (s.topic || '') + '. Sending again creates another mark.' : 'Save these marks to the Nigri gradebook.';
  }
  if (typeof renderResults === 'function') {
    const original = renderResults;
    renderResults = function () { const r = original.apply(this, arguments); try { refreshNigriButton(); } catch (e) {} return r; };
  }
  refreshNigriButton();
})();
